INSERT INTO "projects" VALUES('world-aflame-godot','C:/Users/Admin/dev/world-aflame-godot',NULL,NULL,'published','Active development. Godot 4.7.2 (Standard/non-Mono build required for Web export -- Mono build has zero Web templates). Two rulesets: Classic (turn-based, faithful GDScript port of the web version''s engine + all 150 cards, live-hosted, P2P via NetManager) and Skirmish (new, Snap-inspired simultaneous-reveal mode, 1500 generated keyword-driven cards, engine-verified but UI still landing). Hosted at https://dancockrell.github.io/world-aflame-godot/ via gh-pages branch.','2026-08-26 15:58:37');
INSERT INTO "projects" VALUES('magi-reader-engine','C:\Users\Admin\Downloads\Legacy builds and Assets...if you can''t find something, try here\magi-app','https://github.com/dancockrell/magi-reader-engine','React 19, Vite 8, Playwright, Google Apps Script','active','The illustrated reading engine for language classrooms, named after The Gift of the Magi. One engine, many books: a book is a pack under src/books and src/engine.test.js fails if engine code names a title, an author or a book id. 676 unit tests, 642 e2e across four browser engines. Still in Downloads rather than dev, against the usual rule.','2026-08-26 16:03:24');
INSERT INTO "projects" VALUES('the-gift-of-the-magi-o-henry-magi-reader','C:\Users\Admin\Downloads\Legacy builds and Assets...if you can''t find something, try here\magi-app\src\books\magi','https://github.com/dancockrell/the-gift-of-the-magi-o-henry-magi-reader','book pack: JSON plus media','active','Still inside the engine repository, not yet split out. Blocked on step 2 of PLAN.md, the bring-your-own-pack contract. The engine now has its own fixture book so the tests no longer need this one.','2026-08-26 16:03:24');
INSERT INTO "projects" VALUES('the-raven-edgar-allan-poe-magi-reader','C:\Users\Admin\dev\the-raven-edgar-allan-poe-raven-reader','https://github.com/dancockrell/the-raven-edgar-allan-poe-magi-reader','book pack: JSON, 368 mp3, WebVTT','active','Poe''s poem as a Magi Reader book. Narration and word-level cues recovered from raven-itch-folder zips and committed. Note the folder on disk still says raven-reader while the repo says magi-reader.','2026-08-26 16:03:24');
INSERT INTO "projects" VALUES('magi-reader-classroom-toolkit',NULL,'https://github.com/dancockrell/magi-reader-classroom-toolkit',NULL,'archived','Was raven-classroom, renamed 2026-08-26. Provenance, not a product: the toolkit the engine grew out of, still holding the QR check-in page and the voice generators. Its old description called it the engine behind Raven, Magi and The Long Night, which was wrong on both counts: it is not the engine, and it has nothing to do with The Long Night.','2026-08-26 16:03:24');
INSERT INTO "projects" VALUES('project-42-blockchain','C:/Users/Admin/dev/project-42-blockchain','dancockrell/project-42-blockchain','GDScript library','active','Dual-signature hash-chain ledger, MIT, no server or currency. Renamed from witness-chain. Consumed by world-aflame-godot for Elo. Open issue #1 requests key persistence, DAG timestamp-ordered iteration, an append() payload-validator hook, and a distinct-cosigner-count helper.','2026-08-26 16:17:49');
INSERT INTO "projects" VALUES('claude-config','C:\Users\Admin\dev\claude-config',NULL,'python, git','active','Local git history for the hand-written parts of C:\Users\Admin\.claude. Created 27 Aug 2026 after four sessions edited CLAUDE.md concurrently, one corrupted it through a heredoc, and the only fallbacks were two ad-hoc .bak files at 289 and 472 lines against a live 997. 41 files, about 150 KB, by allowlist. NO REMOTE, deliberately: it holds personal notes and whether it ever gets one is Dan''s call, private if so. Run: python snapshot.py --commit. Guards proved by test_snapshot.py, three of whose four cases pass only by refusing.','2026-08-26 18:07:00');
INSERT INTO "projects" VALUES('quartermaster','C:/Users/Admin/dev/quartermaster',NULL,'Rust, SQLite (rusqlite), MCP over stdio','active','Capability-aware scheduler in Rust. Holds queued work until the tools it needs are verified present by running the command that proves them. Three-state verification (ok/failed/unchecked); unchecked never satisfies a requirement. Public at github.com/dancockrell/quartermaster, 12 commits, 56 tests. Registered as an OpenClaw MCP server (10 tools). Peer-reviewed 27 Aug 2026 by four sessions: 8 real gate bypasses found and fixed, all filed as issues with executable repros. Also ships tools/check-git-remotes.sh and tools/check-cargo-src-intact.sh, both registered as capabilities. Verify: build.cmd test','2026-08-27 09:22:40');
