BEGIN TRANSACTION;
CREATE TABLE dependencies (
    id          INTEGER PRIMARY KEY,
    project     TEXT NOT NULL,
    name        TEXT NOT NULL,
    location    TEXT,
    source_url  TEXT,
    why         TEXT NOT NULL,
    critical    INTEGER NOT NULL DEFAULT 1, updated_at TEXT, check_cmd TEXT,
    UNIQUE (project, name),
    FOREIGN KEY (project) REFERENCES projects(name) ON DELETE CASCADE
);
CREATE TABLE events (
    id          INTEGER PRIMARY KEY,
    ts          TEXT NOT NULL DEFAULT (datetime('now')),
    session     TEXT,
    kind        TEXT NOT NULL CHECK (kind IN
                  ('decision','error','milestone','removal','install')),
    summary     TEXT NOT NULL,
    detail      TEXT
);
CREATE TABLE facts (
    id          INTEGER PRIMARY KEY,
    category    TEXT NOT NULL CHECK (category IN
                  ('user','project','reference','feedback','trap','tool')),
    key         TEXT NOT NULL,
    value       TEXT NOT NULL,
    confidence  TEXT DEFAULT 'verified' CHECK (confidence IN
                  ('verified','reported','inferred')),
    source      TEXT,
    created_at  TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at  TEXT NOT NULL DEFAULT (datetime('now')), check_cmd TEXT,
    UNIQUE (category, key)
);
Cycle documented at magi-reader-engine/docs/PRODUCTION-CYCLE.md: source via curl (never WebFetch relay)
-> author via a generator .mjs script (never hand-typed JSON) -> node tools/check-book.mjs (hard gate)
-> node tools/quality-report.mjs (advisory, fix position/length bias until clean).
Shipped so far, each its own repo with a remote already pushed (mitigates the
files-over-64kb-disappearing trap, since both have a GitHub copy):
  - github.com/dancockrell/the-tell-tale-heart-poe-reader (Poe, quality score 100)
  - github.com/dancockrell/the-cask-of-amontillado-poe-reader (Poe, quality score 96)
