CREATE TABLE projects (
    name        TEXT PRIMARY KEY,
    path        TEXT,
    repo        TEXT,
    stack       TEXT,
    status      TEXT DEFAULT 'active' CHECK (status IN
                  ('active','paused','archived','published')),
    notes       TEXT,
    updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX idx_facts_category ON facts(category);
CREATE INDEX idx_events_ts   ON events(ts);
CREATE INDEX idx_events_kind ON events(kind);
CREATE TRIGGER facts_touch
AFTER UPDATE ON facts FOR EACH ROW
BEGIN
    UPDATE facts SET updated_at = datetime('now') WHERE id = OLD.id;
END;
CREATE TRIGGER projects_touch
AFTER UPDATE ON projects FOR EACH ROW
BEGIN
    UPDATE projects SET updated_at = datetime('now') WHERE name = OLD.name;
END;
CREATE TRIGGER deps_touch
        AFTER UPDATE ON dependencies FOR EACH ROW
        BEGIN UPDATE dependencies SET updated_at = datetime('now') WHERE id = OLD.id; END;
CREATE TRIGGER deps_stamp
        AFTER INSERT ON dependencies FOR EACH ROW WHEN NEW.updated_at IS NULL
        BEGIN UPDATE dependencies SET updated_at = datetime('now') WHERE id = NEW.id; END;
COMMIT;